// Reproduction of CPython's `repr()` for floats.
//
// CPython renders the shortest string that round-trips, switching to
// exponential notation when the decimal point position `decpt` satisfies
// `decpt <= -4 || decpt > 16`, and always keeping a fractional part in
// positional notation.

// Splits a finite, non-zero magnitude into its shortest round-tripping
// digit string and the decimal-point position, so that
// value === 0.<digits> * 10**decpt.
function shortestDigits(value) {
  // toExponential() without an argument yields "as many digits as
  // necessary to uniquely specify the number".
  const exp = value.toExponential();
  const ePos = exp.indexOf('e');
  const mantissa = exp.slice(0, ePos);
  const exponent = Number(exp.slice(ePos + 1));
  const dot = mantissa.indexOf('.');
  const digits = dot === -1 ? mantissa : mantissa.slice(0, dot) + mantissa.slice(dot + 1);
  return { digits, decpt: exponent + 1 };
}

function padExponent(n) {
  const sign = n < 0 ? '-' : '+';
  const abs = String(Math.abs(n));
  return sign + (abs.length < 2 ? '0' + abs : abs);
}

export function pyFloatRepr(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';

  const negative = value < 0 || Object.is(value, -0);
  const magnitude = Math.abs(value);
  if (magnitude === 0) return negative ? '-0.0' : '0.0';

  const { digits, decpt } = shortestDigits(magnitude);
  const sign = negative ? '-' : '';

  if (decpt <= -4 || decpt > 16) {
    const head = digits[0];
    const rest = digits.slice(1);
    return sign + head + (rest.length ? '.' + rest : '') + 'e' + padExponent(decpt - 1);
  }
  if (decpt <= 0) return sign + '0.' + '0'.repeat(-decpt) + digits;
  if (decpt >= digits.length) {
    return sign + digits + '0'.repeat(decpt - digits.length) + '.0';
  }
  return sign + digits.slice(0, decpt) + '.' + digits.slice(decpt);
}

// Parses the textual forms PyYAML's `!!float` constructor accepts.
export function parsePyFloat(text) {
  return Number(text);
}

