// The Python value model, as far as `yaml.safe_load` can produce it.
//
//   None      -> null
//   bool      -> boolean
//   int       -> bigint          (arbitrary precision, like Python)
//   float     -> number
//   str       -> string
//   list      -> Array
//   tuple     -> PyTuple
//   dict      -> PyDict          (insertion ordered, Python key equality)
//   set       -> PySet
//   bytes     -> PyBytes
//   date      -> PyDate
//   datetime  -> PyDateTime

export class PyTuple {
  constructor(items) {
    this.items = items;
  }
}

export class PyBytes {
  constructor(bytes) {
    this.bytes = bytes; // Uint8Array
  }
}

export class PyDate {
  constructor(year, month, day) {
    this.year = year;
    this.month = month;
    this.day = day;
  }

  isoformat() {
    return `${pad(this.year, 4)}-${pad(this.month, 2)}-${pad(this.day, 2)}`;
  }
}

export class PyDateTime extends PyDate {
  // `offset` is the UTC offset in minutes, or null for a naive datetime.
  constructor(year, month, day, hour, minute, second, microsecond, offset) {
    super(year, month, day);
    this.hour = hour;
    this.minute = minute;
    this.second = second;
    this.microsecond = microsecond;
    this.offset = offset;
  }

  // datetime.isoformat(sep) — PyYAML's representer passes a space.
  isoformat(sep = 'T') {
    let out = super.isoformat() + sep +
      `${pad(this.hour, 2)}:${pad(this.minute, 2)}:${pad(this.second, 2)}`;
    if (this.microsecond) out += '.' + pad(this.microsecond, 6);
    if (this.offset !== null) {
      const sign = this.offset < 0 ? '-' : '+';
      const abs = Math.abs(this.offset);
      out += `${sign}${pad(Math.floor(abs / 60), 2)}:${pad(abs % 60, 2)}`;
    }
    return out;
  }
}

function pad(n, width) {
  const s = String(n);
  return s.length >= width ? s : '0'.repeat(width - s.length) + s;
}

// Python hashes `True`/`1`/`1.0` identically and treats them as equal, so
// they collapse to one dict slot. Every other scalar type gets a tag
// prefix so distinct types never collide.
export function hashKey(value) {
  if (value === null) return 'n';
  if (typeof value === 'boolean') return 'i' + (value ? '1' : '0');
  if (typeof value === 'bigint') return 'i' + value.toString();
  if (typeof value === 'number') {
    if (Number.isFinite(value) && Number.isInteger(value)) {
      return 'i' + BigInt(value).toString();
    }
    return 'f' + String(value);
  }
  if (typeof value === 'string') return 's' + value;
  if (value instanceof PyTuple) {
    return 't(' + value.items.map((item) => hashKey(item)).join(',') + ')';
  }
  if (value instanceof PyBytes) {
    return 'b' + Array.from(value.bytes).join(',');
  }
  if (value instanceof PyDateTime) {
    return 'D' + value.isoformat() + '/' + String(value.offset);
  }
  if (value instanceof PyDate) return 'd' + value.isoformat();
  return null; // unhashable (list, dict, set)
}

export class PyDict {
  constructor() {
    this.slots = new Map(); // hash -> { key, value }
  }

  get size() {
    return this.slots.size;
  }

  // Python keeps the *original* key object when a slot is overwritten,
  // and keeps its original insertion position.
  set(key, value) {
    const h = hashKey(key);
    const existing = this.slots.get(h);
    if (existing !== undefined) existing.value = value;
    else this.slots.set(h, { key, value });
  }

  has(key) {
    return this.slots.has(hashKey(key));
  }

  get(key) {
    const slot = this.slots.get(hashKey(key));
    return slot === undefined ? undefined : slot.value;
  }

  *entries() {
    for (const slot of this.slots.values()) yield [slot.key, slot.value];
  }

  items() {
    return Array.from(this.entries());
  }
}

export class PySet {
  constructor() {
    this.dict = new PyDict();
  }

  add(key) {
    this.dict.set(key, null);
  }

  keys() {
    return this.dict.items().map(([key]) => key);
  }
}

