// Error hierarchy mirroring PyYAML's exception classes and their
// `str()` rendering (mark snippets included).

// Characters that terminate a source line for snippet purposes:
// NUL, CR, LF, NEL, LS, PS.
const LINE_BREAKS = '�\r\n  ';

export class Mark {
  constructor(name, index, line, column, buffer, pointer) {
    this.name = name;
    this.index = index;
    this.line = line;
    this.column = column;
    this.buffer = buffer;
    this.pointer = pointer;
  }

  // Reproduces Mark.get_snippet(): a single source line with a caret,
  // truncated with ' ... ' on either side when the line is very long.
  getSnippet(indent = 4, maxLength = 75) {
    if (this.buffer === null || this.buffer === undefined) return null;
    let head = '';
    let start = this.pointer;
    while (start > 0 && LINE_BREAKS.indexOf(this.buffer[start - 1]) === -1) {
      start -= 1;
      if (this.pointer - start > maxLength / 2 - 1) {
        head = ' ... ';
        start += 5;
        break;
      }
    }
    let tail = '';
    let end = this.pointer;
    while (end < this.buffer.length && LINE_BREAKS.indexOf(this.buffer[end]) === -1) {
      end += 1;
      if (end - this.pointer > maxLength / 2 - 1) {
        tail = ' ... ';
        end -= 5;
        break;
      }
    }
    const snippet = head + this.buffer.slice(start, end) + tail;
    return ' '.repeat(indent) + snippet + '\n' +
      ' '.repeat(indent + this.pointer - start + head.length) + '^';
  }

  toString() {
    const snippet = this.getSnippet();
    let where = `  in "${this.name}", line ${this.line + 1}, column ${this.column + 1}`;
    if (snippet !== null) where += ':\n' + snippet;
    return where;
  }
}

export class YAMLError extends Error {
  constructor(message) {
    super(message);
    this.pyName = 'yaml.error.YAMLError';
  }
}

export class MarkedYAMLError extends YAMLError {
  constructor(context, contextMark, problem, problemMark, note) {
    super(problem === null || problem === undefined ? String(context) : problem);
    this.context = context ?? null;
    this.contextMark = contextMark ?? null;
    this.problem = problem ?? null;
    this.problemMark = problemMark ?? null;
    this.note = note ?? null;
    this.pyName = 'yaml.error.MarkedYAMLError';
  }

  toString() {
    const lines = [];
    if (this.context !== null) lines.push(this.context);
    if (this.contextMark !== null &&
      (this.problem === null || this.problemMark === null ||
        this.contextMark.name !== this.problemMark.name ||
        this.contextMark.line !== this.problemMark.line ||
        this.contextMark.column !== this.problemMark.column)) {
      lines.push(this.contextMark.toString());
    }
    if (this.problem !== null) lines.push(this.problem);
    if (this.problemMark !== null) lines.push(this.problemMark.toString());
    if (this.note !== null) lines.push(this.note);
    return lines.join('\n');
  }
}

function markedError(name) {
  return class extends MarkedYAMLError {
    constructor(context, contextMark, problem, problemMark, note) {
      super(context, contextMark, problem, problemMark, note);
      this.pyName = name;
    }
  };
}

function plainError(name) {
  return class extends YAMLError {
    constructor(message) {
      super(message);
      this.pyName = name;
    }
  };
}

export const ReaderError = plainError('yaml.reader.ReaderError');
export const ScannerError = markedError('yaml.scanner.ScannerError');
export const ParserError = markedError('yaml.parser.ParserError');
export const ComposerError = markedError('yaml.composer.ComposerError');
export const ConstructorError = markedError('yaml.constructor.ConstructorError');
export const EmitterError = plainError('yaml.emitter.EmitterError');
export const SerializerError = plainError('yaml.serializer.SerializerError');
export const RepresenterError = plainError('yaml.representer.RepresenterError');

