// Character classification helpers. Written as explicit code-point tests
// so no pattern-matching engine is involved anywhere in the pipeline.

export const NUL = ' ';

export function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

export function isHexDigit(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
}

export function hexValue(ch) {
  if (ch >= '0' && ch <= '9') return ch.charCodeAt(0) - 48;
  if (ch >= 'a' && ch <= 'f') return ch.charCodeAt(0) - 87;
  return ch.charCodeAt(0) - 55;
}

// Characters allowed in an anchor or alias name: alphanumerics plus '-' and '_'.
export function isAnchorChar(ch) {
  return isDigit(ch) || (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') ||
    ch === '-' || ch === '_';
}

export function isLineBreak(ch) {
  return ch === '\n' || ch === '\r' || ch === '' ||
    ch === ' ' || ch === ' ';
}

// A line break or the end-of-stream sentinel.
export function isBreakOrNul(ch) {
  return ch === '\0' || isLineBreak(ch);
}

export function isBlank(ch) {
  return ch === ' ' || ch === '\t';
}

export function isBlankOrEnd(ch) {
  return isBlank(ch) || isBreakOrNul(ch);
}

// The set PyYAML allows in a plain-scalar-terminating position.
export function isFlowIndicator(ch) {
  return ch === ',' || ch === '[' || ch === ']' || ch === '{' || ch === '}';
}

// Reader.NON_PRINTABLE: everything outside this set is rejected outright.
export function isPrintable(codePoint) {
  return codePoint === 0x09 || codePoint === 0x0a || codePoint === 0x0d ||
    (codePoint >= 0x20 && codePoint <= 0x7e) ||
    codePoint === 0x85 ||
    (codePoint >= 0xa0 && codePoint <= 0xd7ff) ||
    (codePoint >= 0xe000 && codePoint <= 0xfffd) ||
    (codePoint >= 0x10000 && codePoint <= 0x10ffff);
}

// Tag/URI characters accepted by Scanner.scan_tag_uri.
export function isUriChar(ch) {
  if (isDigit(ch) || (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z')) return true;
  return '-;/?:@&=+$,_.!~*\'()[]%'.indexOf(ch) !== -1;
}

