import { Mark, ReaderError } from './errors.mjs';
import { isPrintable, NUL } from './chars.mjs';

// Equivalent of yaml.reader.Reader for the `str` input path: the whole
// document is held in memory as a code-point array (matching Python's
// str indexing) with a trailing NUL sentinel.
export class Reader {
  constructor(text) {
    this.name = '<unicode string>';
    this.checkPrintable(text);
    this.buffer = Array.from(text);
    this.buffer.push(NUL);
    this.pointer = 0;
    this.index = 0;
    this.line = 0;
    this.column = 0;
  }

  checkPrintable(text) {
    let offset = 0;
    for (const ch of text) {
      const cp = ch.codePointAt(0);
      if (!isPrintable(cp)) {
        throw new ReaderError(
          `unacceptable character #x${cp.toString(16).padStart(4, '0')}: ` +
          `special characters are not allowed\n  in "<unicode string>", position ${offset}`);
      }
      offset += 1;
    }
  }

  peek(index = 0) {
    const ch = this.buffer[this.pointer + index];
    return ch === undefined ? NUL : ch;
  }

  prefix(length = 1) {
    return this.buffer.slice(this.pointer, this.pointer + length).join('');
  }

  forward(length = 1) {
    while (length) {
      const ch = this.buffer[this.pointer];
      this.pointer += 1;
      this.index += 1;
      if (ch === '\n' || ch === '' || ch === ' ' || ch === ' ' ||
        (ch === '\r' && this.buffer[this.pointer] !== '\n')) {
        this.line += 1;
        this.column = 0;
      } else if (ch !== '﻿') {
        this.column += 1;
      }
      length -= 1;
    }
  }

  getMark() {
    return new Mark(this.name, this.index, this.line, this.column, this.buffer, this.pointer);
  }
}

