// Token objects produced by the scanner. `id` mirrors the `id` class
// attribute PyYAML uses in its own error messages.

export class Token {
  constructor(id, startMark, endMark) {
    this.id = id;
    this.startMark = startMark;
    this.endMark = endMark;
  }
}

export class DirectiveToken extends Token {
  constructor(name, value, startMark, endMark) {
    super('<directive>', startMark, endMark);
    this.name = name;
    this.value = value;
  }
}

export class AliasToken extends Token {
  constructor(value, startMark, endMark) {
    super('<alias>', startMark, endMark);
    this.value = value;
  }
}

export class AnchorToken extends Token {
  constructor(value, startMark, endMark) {
    super('<anchor>', startMark, endMark);
    this.value = value;
  }
}

export class TagToken extends Token {
  // `value` is the [handle, suffix] pair.
  constructor(value, startMark, endMark) {
    super('<tag>', startMark, endMark);
    this.value = value;
  }
}

export class ScalarToken extends Token {
  constructor(value, plain, startMark, endMark, style = null) {
    super('<scalar>', startMark, endMark);
    this.value = value;
    this.plain = plain;
    this.style = style;
  }
}

export function simpleToken(id) {
  return class extends Token {
    constructor(startMark, endMark) {
      super(id, startMark, endMark);
    }
  };
}

export const StreamStartToken = class extends Token {
  constructor(startMark, endMark, encoding = null) {
    super('<stream start>', startMark, endMark);
    this.encoding = encoding;
  }
};
export const StreamEndToken = simpleToken('<stream end>');
export const DocumentStartToken = simpleToken('<document start>');
export const DocumentEndToken = simpleToken('<document end>');
export const BlockSequenceStartToken = simpleToken('<block sequence start>');
export const BlockMappingStartToken = simpleToken('<block mapping start>');
