    } else if (isBlankOrEnd(ch)) {
      suffix = '!';
      this.forward();
    } else {
      let length = 1;
      let useHandle = false;
      while (!isBlankOrEnd(ch)) {
        if (ch === '!') {
          useHandle = true;
          break;
        }
        length += 1;
        ch = this.peek(length);
      }
      if (useHandle) {
        handle = this.scanTagHandle('tag', startMark);
      } else {
        handle = '!';
        this.forward();
      }
      suffix = this.scanTagUri('tag', startMark);
    }
    ch = this.peek();
    if (!isBlankOrEnd(ch)) {
      throw new ScannerError('while scanning a tag', startMark,
        `expected ' ', but found ${pyRepr(ch)}`, this.getMark());
    }
    return new TagToken([handle, suffix], startMark, this.getMark());
  }

  scanBlockScalar(style) {
    const folded = style === '>';
    const chunks = [];
    const startMark = this.getMark();
    this.forward();
    const [chomping, increment] = this.scanBlockScalarIndicators(startMark);
    this.scanBlockScalarIgnoredLine(startMark);

    let minIndent = this.indent + 1;
    if (minIndent < 1) minIndent = 1;
    let indent;
    let breaks;
    let endMark;
    if (increment === null) {
      let maxIndent;
      [breaks, maxIndent, endMark] = this.scanBlockScalarIndentation();
      indent = Math.max(minIndent, maxIndent);
    } else {
      indent = minIndent + increment - 1;
      [breaks, endMark] = this.scanBlockScalarBreaks(indent);
    }
    let lineBreak = '';

    while (this.column === indent && this.peek() !== NUL) {
      chunks.push(...breaks);
      const leadingNonSpace = this.peek() !== ' ' && this.peek() !== '\t';
      let length = 0;
      while (!isBreakOrNul(this.peek(length))) length += 1;
      chunks.push(this.prefix(length));
      this.forward(length);
      lineBreak = this.scanLineBreak();
      [breaks, endMark] = this.scanBlockScalarBreaks(indent);
      if (this.column === indent && this.peek() !== NUL) {
        if (folded && lineBreak === '\n' && leadingNonSpace &&
          this.peek() !== ' ' && this.peek() !== '\t') {
          if (breaks.length === 0) chunks.push(' ');
        } else {
          chunks.push(lineBreak);
        }
      } else {
        break;
      }
    }

    if (chomping !== false) chunks.push(lineBreak);
    if (chomping === true) chunks.push(...breaks);

    return new ScalarToken(chunks.join(''), false, startMark, endMark, style);
  }

  scanBlockScalarIndicators(startMark) {
    let chomping = null;
    let increment = null;
    let ch = this.peek();
    if (ch === '+' || ch === '-') {
      chomping = ch === '+';
      this.forward();
      ch = this.peek();
      if (isDigit(ch)) {
        increment = Number(ch);
        if (increment === 0) {
          throw new ScannerError('while scanning a block scalar', startMark,
            'expected indentation indicator in the range 1-9, but found 0', this.getMark());
        }
        this.forward();
      }
    } else if (isDigit(ch)) {
      increment = Number(ch);
      if (increment === 0) {
        throw new ScannerError('while scanning a block scalar', startMark,
          'expected indentation indicator in the range 1-9, but found 0', this.getMark());
      }
      this.forward();
      ch = this.peek();
      if (ch === '+' || ch === '-') {
        chomping = ch === '+';
        this.forward();
      }
    }
    ch = this.peek();
    if (!isBlankOrEnd(ch)) {
      throw new ScannerError('while scanning a block scalar', startMark,
        `expected chomping or indentation indicators, but found ${pyRepr(ch)}`, this.getMark());
    }
    return [chomping, increment];
  }

  scanBlockScalarIgnoredLine(startMark) {
    while (this.peek() === ' ') this.forward();
    if (this.peek() === '#') {
      while (!isBreakOrNul(this.peek())) this.forward();
    }
    const ch = this.peek();
    if (!isBreakOrNul(ch)) {
      throw new ScannerError('while scanning a block scalar', startMark,
        `expected a comment or a line break, but found ${pyRepr(ch)}`, this.getMark());
    }
    this.scanLineBreak();
  }

  scanBlockScalarIndentation() {
    const chunks = [];
    let maxIndent = 0;
    let endMark = this.getMark();
    while (isBlank(this.peek()) || isLineBreak(this.peek())) {
      if (this.peek() !== ' ') {
        chunks.push(this.scanLineBreak());
        endMark = this.getMark();
      } else {
        this.forward();
        if (this.column > maxIndent) maxIndent = this.column;
      }
    }
    return [chunks, maxIndent, endMark];
  }

  scanBlockScalarBreaks(indent) {
    const chunks = [];
    let endMark = this.getMark();
    while (this.column < indent && this.peek() === ' ') this.forward();
    while (isLineBreak(this.peek())) {
      chunks.push(this.scanLineBreak());
      endMark = this.getMark();
      while (this.column < indent && this.peek() === ' ') this.forward();
    }
    return [chunks, endMark];
  }

  scanFlowScalar(style) {
    const double = style === '"';
    const chunks = [];
    const startMark = this.getMark();
    const quote = this.peek();
    this.forward();
    chunks.push(...this.scanFlowScalarNonSpaces(double, startMark));
    while (this.peek() !== quote) {
      chunks.push(...this.scanFlowScalarSpaces(double, startMark));
      chunks.push(...this.scanFlowScalarNonSpaces(double, startMark));
    }
    this.forward();
    return new ScalarToken(chunks.join(''), false, startMark, this.getMark(), style);
  }

  scanFlowScalarNonSpaces(double, startMark) {
    const chunks = [];
    for (;;) {
      let length = 0;
      for (;;) {
        const ch = this.peek(length);
        if (isBlankOrEnd(ch) || ch === '\'' || ch === '"' || ch === '\\') break;
        length += 1;
      }
      if (length !== 0) {
        chunks.push(this.prefix(length));
        this.forward(length);
      }
      let ch = this.peek();
      if (!double && ch === '\'' && this.peek(1) === '\'') {
        chunks.push('\'');
        this.forward(2);
      } else if ((double && ch === '\'') || (!double && (ch === '"' || ch === '\\'))) {
        chunks.push(ch);
        this.forward();
      } else if (double && ch === '\\') {
        this.forward();
        ch = this.peek();
        if (ESCAPE_REPLACEMENTS.has(ch)) {
          chunks.push(ESCAPE_REPLACEMENTS.get(ch));
          this.forward();
        } else if (ESCAPE_CODES.has(ch)) {
          const length2 = ESCAPE_CODES.get(ch);
          this.forward();
          for (let k = 0; k < length2; k += 1) {
            if (!isHexDigit(this.peek(k))) {
              throw new ScannerError('while scanning a double-quoted scalar', startMark,
                `expected escape sequence of ${length2} hexadecimal numbers, ` +
                `but found ${pyRepr(this.peek(k))}`, this.getMark());
            }
          }
          let code = 0;
          for (let k = 0; k < length2; k += 1) code = code * 16 + hexValue(this.peek(k));
          chunks.push(safeFromCodePoint(code, startMark, this.getMark()));
          this.forward(length2);
        } else if (isLineBreak(ch)) {
          this.scanLineBreak();
          chunks.push(...this.scanFlowScalarBreaks(double, startMark));
        } else {
          throw new ScannerError('while scanning a double-quoted scalar', startMark,
            `found unknown escape character ${pyRepr(ch)}`, this.getMark());
        }
      } else {
        return chunks;
      }
    }
  }

  scanFlowScalarSpaces(double, startMark) {
    const chunks = [];
    let length = 0;
    while (isBlank(this.peek(length))) length += 1;
    const whitespaces = this.prefix(length);
    this.forward(length);
    const ch = this.peek();
    if (ch === NUL) {
      throw new ScannerError('while scanning a quoted scalar', startMark,
        'found unexpected end of stream', this.getMark());
    }
    if (isLineBreak(ch)) {
      const lineBreak = this.scanLineBreak();
      const breaks = this.scanFlowScalarBreaks(double, startMark);
      if (lineBreak !== '\n') chunks.push(lineBreak);
      else if (breaks.length === 0) chunks.push(' ');
      chunks.push(...breaks);
    } else {
      chunks.push(whitespaces);
    }
    return chunks;
  }

  scanFlowScalarBreaks(double, startMark) {
    const chunks = [];
    for (;;) {
      const prefix = this.prefix(3);
      if ((prefix === '---' || prefix === '...') && isBlankOrEnd(this.peek(3))) {
        throw new ScannerError('while scanning a quoted scalar', startMark,
          'found unexpected document separator', this.getMark());
      }
      while (isBlank(this.peek())) this.forward();
      if (isLineBreak(this.peek())) chunks.push(this.scanLineBreak());
      else return chunks;
    }
  }

  scanPlain() {
    const chunks = [];
    const startMark = this.getMark();
    let endMark = startMark;
    const indent = this.indent + 1;
    let spaces = [];
    for (;;) {
      if (this.peek() === '#') break;
      let length = 0;
      for (;;) {
        const ch = this.peek(length);
        if (isBlankOrEnd(ch)) break;
        if (ch === ':' && isBlankOrEnd(this.peek(length + 1))) break;
        if (this.flowLevel !== 0 && isFlowIndicator(ch)) break;
        if (this.flowLevel !== 0 && ch === ':' &&
          !(isBlankOrEnd(this.peek(length + 1)) || isFlowIndicator(this.peek(length + 1)))) {
          this.forward(length);
          throw new ScannerError('while scanning a plain scalar', startMark,
            "found unexpected ':'", this.getMark(),
            'Please check http://pyyaml.org/wiki/YAMLColonInFlowContext for details.');
        }
        length += 1;
      }
      if (length === 0) break;
      this.allowSimpleKey = false;
      chunks.push(...spaces);
      chunks.push(this.prefix(length));
      this.forward(length);
      endMark = this.getMark();
      spaces = this.scanPlainSpaces(indent, startMark);
      if (spaces === null || spaces.length === 0 || this.peek() === '#' ||
        (this.flowLevel === 0 && this.column < indent)) {
        break;
      }
    }
    return new ScalarToken(chunks.join(''), true, startMark, endMark);
  }

  scanPlainSpaces(indent, startMark) {
    const chunks = [];
    let length = 0;
    while (this.peek(length) === ' ') length += 1;
    const whitespaces = this.prefix(length);
    this.forward(length);
    const ch = this.peek();
    if (isLineBreak(ch)) {
      const lineBreak = this.scanLineBreak();
      this.allowSimpleKey = true;
      const prefix = this.prefix(3);
      if ((prefix === '---' || prefix === '...') && isBlankOrEnd(this.peek(3))) return null;
      const breaks = [];
      while (this.peek() === ' ' || isLineBreak(this.peek())) {
        if (this.peek() === ' ') {
          this.forward();
        } else {
          breaks.push(this.scanLineBreak());
          const p = this.prefix(3);
          if ((p === '---' || p === '...') && isBlankOrEnd(this.peek(3))) return null;
        }
      }
      if (lineBreak !== '\n') chunks.push(lineBreak);
      else if (breaks.length === 0) chunks.push(' ');
      chunks.push(...breaks);
    } else if (whitespaces) {
      chunks.push(whitespaces);
    }
    return chunks;
  }

  scanTagHandle(name, startMark) {
    let ch = this.peek();
    if (ch !== '!') {
      throw new ScannerError(`while scanning a ${name}`, startMark,
        `expected '!', but found ${pyRepr(ch)}`, this.getMark());
    }
    let length = 1;
    ch = this.peek(length);
    if (ch !== ' ') {
      while (isAnchorChar(ch)) {
        length += 1;
        ch = this.peek(length);
      }
      if (ch !== '!') {
        this.forward(length);
        throw new ScannerError(`while scanning a ${name}`, startMark,
          `expected '!', but found ${pyRepr(ch)}`, this.getMark());
      }
      length += 1;
    }
    const value = this.prefix(length);
    this.forward(length);
    return value;
  }

  scanTagUri(name, startMark) {
    const chunks = [];
    let length = 0;
    let ch = this.peek(length);
    while (isUriChar(ch)) {
      if (ch === '%') {
        chunks.push(this.prefix(length));
        this.forward(length);
        length = 0;
        chunks.push(this.scanUriEscapes(name, startMark));
      } else {
        length += 1;
      }
      ch = this.peek(length);
    }
    if (length !== 0) {
      chunks.push(this.prefix(length));
      this.forward(length);
      length = 0;
    }
    if (chunks.length === 0) {
      throw new ScannerError(`while parsing a ${name}`, startMark,
        `expected URI, but found ${pyRepr(ch)}`, this.getMark());
    }
    return chunks.join('');
  }

  scanUriEscapes(name, startMark) {
    const bytes = [];
    const mark = this.getMark();
    while (this.peek() === '%') {
      this.forward();
      for (let k = 0; k < 2; k += 1) {
        if (!isHexDigit(this.peek(k))) {
          throw new ScannerError(`while scanning a ${name}`, startMark,
            'expected URI escape sequence of 2 hexadecimal numbers, but found ' +
            pyRepr(this.peek(k)), this.getMark());
        }
      }
      bytes.push(hexValue(this.peek(0)) * 16 + hexValue(this.peek(1)));
      this.forward(2);
    }
    try {
      return new TextDecoder('utf-8', { fatal: true }).decode(new Uint8Array(bytes));
    } catch (err) {
      throw new ScannerError(`while scanning a ${name}`, startMark, String(err.message), mark);
    }
  }

  scanLineBreak() {
    const ch = this.peek();
    if (ch === '\r' || ch === '\n' || ch === '') {
      if (this.prefix(2) === '\r\n') this.forward(2);
      else this.forward();
      return '\n';
    }
    if (ch === ' ' || ch === ' ') {
      this.forward();
      return ch;
    }
    return '';
  }
}

function safeFromCodePoint(code, startMark, mark) {
  if (code > 0x10ffff || (code >= 0xd800 && code <= 0xdfff)) {
    throw new ScannerError('while scanning a double-quoted scalar', startMark,
      `found undefined escape character`, mark);
  }
  return String.fromCodePoint(code);
}

// Renders a character the way Python's repr() does inside error messages.
export function pyRepr(ch) {
  if (ch === NUL) return "'\\x00'";
  const cp = ch.codePointAt(0);
  if (ch === '\\') return "'\\\\'";
  if (ch === '\'') return '"\'"';
  if (ch === '\n') return "'\\n'";
  if (ch === '\r') return "'\\r'";
  if (ch === '\t') return "'\\t'";
  if (cp < 0x20 || cp === 0x7f) return `'\\x${cp.toString(16).padStart(2, '0')}'`;
  return `'${ch}'`;
}
